#!/usr/bin/env node
import {
  mkdirSync, rmSync, existsSync, readdirSync, statSync, writeFileSync, copyFileSync
} from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { releasePathFor, resolveShippingFiles } from "../lib/shipping-surface.mjs";
import { assembleBrowserFlowPackage } from "./render-browser-flow-surfaces.mjs";
import { assertReleaseClosure } from "./release-closure.mjs";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const manifestPath = resolve(repoRoot, "scripts/publish/bundle-allowlist.json");
// Released bundle lives OUTSIDE the source repo, as a sibling directory, so it
// is a clearly-visible standalone project rather than a hidden subdir.
// BROWSER_FLOW_RELEASE_DIR overrides the destination (used for safe
// verification/smoke builds into a throwaway temp dir without clobbering the
// real release sibling). Default is unchanged.
const releaseDir = process.env.BROWSER_FLOW_RELEASE_DIR
  ? resolve(process.env.BROWSER_FLOW_RELEASE_DIR)
  : resolve(repoRoot, "..", "browser-flow-released");
const RELEASE_LABEL = process.env.BROWSER_FLOW_RELEASE_DIR ? releaseDir : "../browser-flow-released";
const STAMP = ".bundle-stamp.json";
const BUNDLE_IGNORE = ".gitignore";

/** Top-level file names to skip during the leak walk (generated by this script or OS noise). */
const SKIP_TOP_FILES = new Set([STAMP, BUNDLE_IGNORE]);

/** Wipe the release dir contents except its release-repo .git, then copy the allowlist in. */
function sync() {
  const files = resolveShippingFiles(repoRoot, manifestPath);
  /** @type {string[]} */
  const copied = [];
  if (existsSync(releaseDir)) {
    for (const name of readdirSync(releaseDir)) {
      if (name === ".git") continue;
      rmSync(resolve(releaseDir, name), { recursive: true, force: true });
    }
  } else {
    mkdirSync(releaseDir, { recursive: true });
  }
  for (const rel of files) {
    const dest = resolve(releaseDir, releasePathFor(rel));
    mkdirSync(dirname(dest), { recursive: true });
    copyFileSync(resolve(repoRoot, rel), dest);
    copied.push(releasePathFor(rel));
  }
  const packageRoot = resolve(releaseDir, "skills", "browser-flow");
  assembleBrowserFlowPackage(repoRoot, packageRoot);
  copyFileSync(resolve(repoRoot, "scripts/publish/bundle-gitignore"), resolve(releaseDir, BUNDLE_IGNORE));
  copied.push(...listRelativeFiles(packageRoot));
  return copied;
}

/**
 * @param {string} dir
 * @returns {string[]}
 */
function listRelativeFiles(dir) {
  /** @type {string[]} */
  const out = [];
  /**
   * @param {string} abs
   * @param {string} rel
   */
  const walk = (abs, rel) => {
    for (const name of readdirSync(abs)) {
      const child = resolve(abs, name);
      const childRel = rel ? `${rel}/${name}` : name;
      if (statSync(child).isDirectory()) {
        walk(child, childRel);
      } else {
        out.push(childRel);
      }
    }
  };
  walk(dir, "skills/browser-flow");
  return out;
}

/**
 * Every file in the release dir (except .git, generated stamp, generated
 * .gitignore, and .bundle-stamp.json) must be allowlisted. Runtime-generated
 * dirs such as artifacts/profiles/raw journals are not skipped here; finding
 * them in the public release tree is a build failure.
 * @param {string[]} files
 */
function assertNoLeak(files) {
  const allow = new Set(files);
  /** @type {string[]} */
  const leaks = [];
  const walk = (/** @type {string} */ rel) => {
    for (const name of readdirSync(resolve(releaseDir, rel || "."))) {
      if (!rel && name === ".git") continue;
      // Skip known generated/OS top-level files
      if (!rel && SKIP_TOP_FILES.has(name)) continue;
      const childRel = rel ? `${rel}/${name}` : name;
      if (statSync(resolve(releaseDir, childRel)).isDirectory()) {
        walk(childRel);
      } else if (!allow.has(childRel)) {
        leaks.push(childRel);
      }
    }
  };
  walk("");
  if (leaks.length) {
    for (const l of leaks) process.stderr.write(`LEAK ${l}\n`);
    process.stderr.write(`\nbuild-bundle FAILED: ${leaks.length} path(s) outside the allowlist.\n`);
    process.exit(1);
  }
}

function main() {
  const files = sync();
  assertNoLeak(files);
  assertReleaseClosure(releaseDir);
  writeFileSync(
    resolve(releaseDir, STAMP),
    JSON.stringify({ builtAt: new Date().toISOString(), fileCount: files.length }, null, 2) + "\n"
  );
  process.stdout.write(`build-bundle OK → ${RELEASE_LABEL}/ (${files.length} files)\n`);
  process.stdout.write(`Next: cd ${RELEASE_LABEL} && (git init if needed) && git add -A && git commit && git push\n`);
}

main();
